//! R10 deterministic Size Map parity gate; exact decimal step arithmetic to 12 places; review only.
use serde_json::json;
const SCALE:u128=1_000_000_000_000;fn gcd(mut a:u128,mut b:u128)->u128{while b!=0{let r=a%b;a=b;b=r}a}fn lcm(a:u128,b:u128)->Option<u128>{if a==0||b==0{return None}a.checked_div(gcd(a,b))?.checked_mul(b)}fn dec(s:&str)->Option<u128>{let mut p=s.split('.');let whole=p.next()?.parse::<u128>().ok()?;let frac=p.next().unwrap_or("");if p.next().is_some()||frac.len()>12{return None}let mut f=frac.to_string();while f.len()<12{f.push('0')}whole.checked_mul(SCALE)?.checked_add(f.parse::<u128>().ok()?)}fn common(a:&str,b:&str)->Option<u128>{lcm(dec(a)?,dec(b)?)}fn ceil_step(v:u128,s:u128)->u128{((v+s-1)/s)*s}fn floor_step(v:u128,s:u128)->u128{(v/s)*s}
fn main(){let tests=[("6dp","0.000001","0.000003","0.000003"),("8dp","0.00000001","0.00000003","0.00000003"),("12dp","0.000000000001","0.000000000003","0.000000000003"),("lcm12","0.000000000002","0.000000000003","0.000000000006"),("mixed","0.000001","0.000000000003","0.000003"),("coarse","0.002","0.003","0.006")];let mut f=vec![];for(n,a,b,w)in tests{let got=common(a,b);let want=dec(w);if got!=want{f.push(json!({"case":n,"got":got.map(|x|x.to_string()),"want":want.map(|x|x.to_string())}))}}let s=dec("0.000000000003").unwrap();let rounding=ceil_step(dec("0.000000000004").unwrap(),s)==dec("0.000000000006").unwrap()&&floor_step(dec("0.000000000008").unwrap(),s)==dec("0.000000000006").unwrap();println!("{}",json!({"r10_exact_step12_gate":f.is_empty()&&rounding,"cases":tests.len()+1,"failures":f,"ceil_floor_exact":rounding,"scale":SCALE.to_string(),"trading":false}));}
